cpuT.innerHTML='';gpuT.innerHTML='';
if(mode=='eager'){
for(var i=0;i&lt;6;i++){blk(cpuT,1+i*16.4,7,'pe-cpu','launch');blk(gpuT,8.4+i*16.4,7.6,'pe-gpu','kernel');if(i&lt;5)blk(gpuT,16+i*16.4,7.2,'pe-idle','idle');}
