var u=Math.min(100,Math.round(100*(1-Math.exp(-v/230))));
q('#peUtil').style.width=u+'%';q('#peUtilV').textContent=u+'%';
q('#peState').textContent=v&lt;512?'Under-filled':(v&lt;1200?'Saturated':'Throughput-bound');
